import React,{useMemo,useState} from 'react';
import {AlertTriangle,ArrowRight,CheckCircle2,ChevronLeft,ChevronRight,Database,FileText,GitBranch,Plus,Trash2} from 'lucide-react';
import {decodeSourceFile,inspectSourceText} from './sourceArchive.js';
import {EvidenceAttachment,PreservedCapability} from './SemanticMaintenanceControls.jsx';
import {completePropertyMappings,deriveBindingDraft,expressionReferences,prepareSemanticSave,semanticSaveProblems} from './semanticMaintenance.js';
import {assetFor,assetLabel,catalogDatasets,catalogFields,datasetFor,datasetLabel,exactRefKey,expressionLabel,fieldFor,fieldLabel,maintenanceIssues,physicalKey,planCatalogMigration,propertyLabel,showValue,typeTitles,valueTitles} from './semanticUiModel.js';

const copy=value=>JSON.parse(JSON.stringify(value));
const refOf=asset=>({workspace_id:asset.workspace_id,asset_id:asset.asset_id,asset_type:asset.asset_type,revision:asset.revision});
const unitUnknown=()=>({kind:'UNKNOWN',code:null,currency:null,scale:null,authority:'UNKNOWN'});
const nullable=value=>value===''?null:value;
const sameAsset=(a,b)=>exactRefKey(a)===exactRefKey(b);

function Field({label,help,children,wide=false}){return <label className={`field sw-field ${wide?'wide':''}`}><span>{label}</span>{children}{help&&<small>{help}</small>}</label>;}
function Text({label,value,onChange,help,multiline=false,nullableValue=false}){return <Field label={label} help={help} wide={multiline}>{multiline?<textarea value={value??''} onChange={e=>onChange(nullableValue?nullable(e.target.value):e.target.value)} rows={3}/>:<input value={value??''} onChange={e=>onChange(nullableValue?nullable(e.target.value):e.target.value)}/>}</Field>;}
function Select({label,value,onChange,options,help,nullableValue=false}){return <Field label={label} help={help}><select value={value??''} onChange={e=>onChange(nullableValue?nullable(e.target.value):e.target.value)}>{options.map(option=>{const [id,title]=Array.isArray(option)?option:[option,showValue(option)];return <option key={String(id)} value={id}>{title}</option>;})}</select></Field>;}
function Section({title,description,children,action}){return <section className="sw-section"><header><div><h3>{title}</h3>{description&&<p>{description}</p>}</div>{action}</header><div className="sw-form-grid">{children}</div></section>;}
function Remove({onClick,label='移除'}){return <button type="button" className="icon-btn sw-remove" aria-label={label} title={label} onClick={onClick}><Trash2 size={15}/></button>;}
function Notice({children}){return <div className="sw-notice"><AlertTriangle size={16}/><span>{children}</span></div>;}
function JsonReadOnly({value,title='查看结构化只读快照'}){return <details className="sw-technical"><summary>{title}</summary><pre>{JSON.stringify(value,null,2)}</pre></details>;}

export function AssetSelect({label,value,onChange,context,types,nullableValue=false,help}){
 const items=(context.assets||[]).filter(item=>(item.is_current!==false||sameAsset(item.asset_ref,value))&&(!types||types.includes(item.asset_revision.asset_type)));
 const selected=items.some(item=>sameAsset(item.asset_ref,value));
 return <Field label={label} help={help}><select value={exactRefKey(value)} onChange={e=>{const item=items.find(candidate=>exactRefKey(candidate.asset_ref)===e.target.value);onChange(item?copy(item.asset_ref):null);}}><option value="">{nullableValue?'未指定':'请选择准确修订'}</option>{value&&!selected&&<option value={exactRefKey(value)}>{assetLabel(value,context)}</option>}{items.map(item=><option key={exactRefKey(item.asset_ref)} value={exactRefKey(item.asset_ref)}>{item.asset_revision.name} · r{item.asset_ref.revision}{item.is_current===false?'（历史）':''} · {typeTitles[item.asset_ref.asset_type]}</option>)}</select></Field>;
}

function AssetChecks({label,values=[],onChange,context,types,allowedRefs}){
 const [query,setQuery]=useState('');
 const items=(context.assets||[]).filter(item=>(item.is_current!==false||values.some(ref=>sameAsset(ref,item.asset_ref)))&&(!types||types.includes(item.asset_revision.asset_type))&&(!allowedRefs||allowedRefs.some(ref=>sameAsset(ref,item.asset_ref))));
 const visible=items.filter(item=>`${item.asset_revision.name} ${item.asset_revision.definition}`.toLowerCase().includes(query.toLowerCase()));
 return <fieldset className="sw-check-field wide"><legend>{label} · 已选 {values.length} 项</legend>{items.length>6&&<input className="sm-choice-search" aria-label={'搜索'+label} placeholder="输入名称筛选可复用资产" value={query} onChange={e=>setQuery(e.target.value)}/>}<div className="sw-check-grid">{visible.map(item=><label key={exactRefKey(item.asset_ref)}><input type="checkbox" checked={values.some(ref=>sameAsset(ref,item.asset_ref))} onChange={e=>onChange(e.target.checked?[...values,copy(item.asset_ref)]:values.filter(ref=>!sameAsset(ref,item.asset_ref)))}/><span>{item.asset_revision.name}<small>r{item.asset_ref.revision}{item.is_current===false?' · 已选历史修订':''}</small></span></label>)}</div>{!visible.length&&<p className="sem-form-hint">{items.length?'没有匹配项，请调整搜索。':'暂无可复用项，可先保存当前支持的定义或附上新依据。'}</p>}</fieldset>;
}

function MemberChecks({label,values=[],onChange,context}){return <fieldset className="sw-check-field"><legend>{label}</legend><div className="sw-check-grid">{(context.users||[]).map(user=><label key={user.id}><input type="checkbox" checked={values.map(String).includes(String(user.id))} onChange={e=>onChange(e.target.checked?[...values,String(user.id)]:values.filter(id=>String(id)!==String(user.id)))}/>{user.display_name||user.username}</label>)}</div></fieldset>;}
export function CatalogFieldSelect({label,value,onChange,context,datasetRef,help,nullableValue=false}){
 const fields=catalogFields(context).filter(entry=>!datasetRef||entry.ref.catalog_snapshot_id===datasetRef.catalog_snapshot_id&&entry.ref.datasource_id===datasetRef.datasource_id&&entry.ref.dataset_id===datasetRef.dataset_id);
 const selected=fields.some(entry=>physicalKey(entry.ref)===physicalKey(value));
 return <Field label={label} help={help}><select value={physicalKey(value)} onChange={e=>onChange(copy(fields.find(entry=>physicalKey(entry.ref)===e.target.value)?.ref||null))}><option value="">{nullableValue?'未映射 / 未确认':'请选择目录字段'}</option>{value&&!selected&&<option value={physicalKey(value)}>{fieldLabel(value,context)}</option>}{fields.map(entry=><option key={physicalKey(entry.ref)} value={physicalKey(entry.ref)}>{entry.label} · {entry.dataset.logical_locator}.{entry.field.field_id} · {entry.field.data_type} · 目录{entry.ref.catalog_snapshot_id.slice(-10)}</option>)}</select></Field>;
}
function DatasetSelect({label,value,onChange,context}){const datasets=catalogDatasets(context);return <Field label={label} help="引用精确目录快照。选择其他表不会自动迁移已有字段映射。"><select value={physicalKey(value)} onChange={e=>onChange(copy(datasets.find(entry=>physicalKey(entry.ref)===e.target.value)?.ref||null))}><option value="">选择数据源、表与目录版本</option>{datasets.map(entry=><option key={physicalKey(entry.ref)} value={physicalKey(entry.ref)}>{entry.dataset.business_definition?.name_zh||entry.dataset.logical_locator} · {entry.dataset.namespace}.{entry.dataset.physical_name} · {entry.snapshot.catalog_snapshot_id.slice(-12)}</option>)}</select></Field>;}
function PropertySelect({label,value,onChange,context,entityRef,help,nullableValue=false}){const entities=(context.assets||[]).filter(item=>item.asset_revision.asset_type==='entity'&&(!entityRef||sameAsset(item.asset_ref,entityRef))),options=entities.flatMap(item=>(item.asset_revision.spec.properties||[]).map(property=>({ref:{entity_ref:item.asset_ref,property_id:property.property_id},label:`${item.asset_revision.name} · ${property.name} (${property.data_type})`})));const key=ref=>ref?`${exactRefKey(ref.entity_ref)}|${ref.property_id}`:'';return <Field label={label} help={help}><select value={key(value)} onChange={e=>onChange(copy(options.find(option=>key(option.ref)===e.target.value)?.ref||null))}><option value="">{nullableValue?'未指定 / 待确认':'选择业务属性'}</option>{value&&!options.some(option=>key(option.ref)===key(value))&&<option value={key(value)}>{propertyLabel(value,context)}</option>}{options.map(option=><option key={key(option.ref)} value={key(option.ref)}>{option.label}</option>)}</select></Field>;}
function StringList({label,values=[],onChange,help}){return <Field label={label} help={help} wide><textarea rows={2} value={values.join('\n')} onChange={e=>onChange(e.target.value.split('\n'))}/></Field>;}
function RefFieldList({label,values=[],onChange,context,datasetRef}){return <div className="wide"><strong className="sw-small-title">{label}</strong>{values.map((value,index)=><div className="sw-inline-row" key={index}><CatalogFieldSelect label={`字段 ${index+1}`} value={value} onChange={next=>onChange(values.map((old,i)=>i===index?next:old))} context={context} datasetRef={datasetRef}/><Remove onClick={()=>onChange(values.filter((_,i)=>i!==index))}/></div>)}<button type="button" className="btn" onClick={()=>onChange([...values,null])}><Plus size={13}/>添加字段</button></div>;}

export function AggregateControl({value,onChange,kind,context,entityRef,datasetRef}){
 const simple=value?.op==='call'&&['count_distinct','count','avg','sum','min','max'].includes(value.function)&&value.args?.length===1&&value.args[0]?.op===kind;
 const supported=simple&&['count_distinct','count','avg'].includes(value.function);
 const make=(fn,reference)=>({op:'call',function:fn,args:[kind==='property'?{op:'property',property_ref:reference}:{op:'field',field_ref:reference}]});
 const reference=simple?value.args[0][kind+'_ref']:null;
 return <div className="sw-aggregate wide"><p className="sw-expression-summary">{expressionLabel(value,context)}</p>{!simple?<><Notice>当前计算为复杂表达式，保留现有定义。本版受控执行仅支持去重计数、计数与评分平均值；金额或复杂派生仍由服务端阻断。</Notice><button type="button" className="btn" onClick={()=>onChange(make('count_distinct',null))}>改为单属性聚合（将替换现有计算）</button><JsonReadOnly value={value}/></>:<><div className="sw-form-grid"><Select label="计算方式" value={value.function} options={[['count_distinct','按标识去重计数'],['count','统计非空值个数'],['avg','平均值（本期仅评分）'],...(!supported?[[value.function,showValue(value.function)+'（当前定义，暂不支持执行）']]:[])]} onChange={fn=>onChange(make(fn,reference))}/>{kind==='property'?<PropertySelect label={value.function==='count_distinct'?'去重的业务标识':'参与计算的业务属性'} value={reference} onChange={next=>onChange(make(value.function,next))} context={context} entityRef={entityRef}/>:<CatalogFieldSelect label={value.function==='count_distinct'?'去重的物理字段':'参与计算的物理字段'} value={reference} onChange={next=>onChange(make(value.function,next))} context={context} datasetRef={datasetRef}/>}</div>{!supported&&<Notice>该计算方式当前可维护，执行支持尚未开放。</Notice>}</>}</div>;
}

function UnitControl({value,onChange}){const unit=value||unitUnknown(),set=(key,next)=>onChange({...unit,[key]:next});return <><Select label="计量类型" value={unit.kind} onChange={next=>set('kind',next)} options={['UNKNOWN','COUNT','NUMBER','CURRENCY','RATIO','DURATION']}/><Text label="单位编码" value={unit.code} onChange={next=>set('code',next)} nullableValue help="例如 count、score。未知留空，不自动补币种。"/>{unit.kind==='CURRENCY'&&<Text label="币种" value={unit.currency} onChange={next=>set('currency',next)} nullableValue help="须有来源依据，例如 BRL；不能根据名称推断。"/>}<Field label="数值倍率"><input type="number" min="0" step="any" value={unit.scale??''} onChange={e=>set('scale',e.target.value===''?null:Number(e.target.value))}/></Field><Select label="单位依据" value={unit.authority} onChange={next=>set('authority',next)} options={['UNKNOWN','SYNTHETIC_ONLY','CONFIRMED']}/></>;}

function BasicFields({asset,onChange,context}){
 const set=(key,value)=>onChange({...asset,[key]:value});
 return <><Section title="基本业务定义" description="用业务语言写清楚要算什么、统计哪些记录。"><Text label="中文名称 *" value={asset.name} onChange={value=>set('name',value)}/><Text label="业务定义与边界 *" value={asset.definition} onChange={value=>set('definition',value)} multiline help="例如：按下单时间，统计订单编号的去重数量；不代表已支付订单数。"/><div className="wide sm-aliases"><strong className="sw-small-title">常用问法 / 别名 <small>可选，用于匹配用户问题</small></strong>{(asset.aliases||[]).map((alias,index)=><div className="sm-alias-row" key={index}><input aria-label={'别名 '+(index+1)} placeholder="例如：订单量" value={alias.text} onChange={e=>set('aliases',asset.aliases.map((old,i)=>i===index?{...old,text:e.target.value}:old))}/><Remove label={'移除别名 '+(index+1)} onClick={()=>set('aliases',asset.aliases.filter((_,i)=>i!==index))}/></div>)}<button className="btn" type="button" onClick={()=>set('aliases',[...(asset.aliases||[]),{text:'',language:'zh-CN',kind:'EXACT_ALIAS',scope:'当前资产'}])}><Plus size={13}/>添加别名</button></div></Section>
 <details className="sw-more"><summary>业务域、有效期与别名元数据 · 按需维护</summary><div className="sw-form-grid"><AssetSelect label="所属业务域" value={asset.domain_ref} onChange={value=>set('domain_ref',value)} context={context} types={['domain']} nullableValue/><Text label="生效时间（ISO 8601，含时区）" value={asset.validity?.from} onChange={value=>set('validity',{...asset.validity,from:value})} nullableValue/><Text label="失效时间（ISO 8601，含时区）" value={asset.validity?.to} onChange={value=>set('validity',{...asset.validity,to:value})} nullableValue/>{(asset.aliases||[]).map((alias,index)=><div className="sw-array-card wide" key={index}><strong>{alias.text||'未命名别名'}</strong><div className="sw-form-grid"><Select label="别名类型" value={alias.kind} options={['EXACT_ALIAS','ABBREVIATION']} onChange={value=>set('aliases',asset.aliases.map((old,i)=>i===index?{...old,kind:value}:old))}/><Text label="语言" value={alias.language} onChange={value=>set('aliases',asset.aliases.map((old,i)=>i===index?{...old,language:value}:old))}/><Text label="适用范围记录" value={alias.scope} onChange={value=>set('aliases',asset.aliases.map((old,i)=>i===index?{...old,scope:value}:old))}/></div></div>)}</div><p className="sem-form-hint">当前匹配使用别名文本；范围、语言和类型只作记录，尚不参与通用消歧。有效期留空表示未设置该边界，不等于已经过业务审核。</p></details></>;
}


function ResponsibilityFields({asset,onChange,context}){
 const set=(key,value)=>onChange({...asset,[key]:value});
 return <><Section title="依据与责任" description="可复用已有依据，也可直接附上原文。新材料与本次修订一起保存，仍需审核。"><AssetChecks label="复用已有来源或证据" values={asset.provenance_refs} onChange={value=>set('provenance_refs',value)} context={context} types={['source','evidence','claim']}/><EvidenceAttachment items={context.attachments} onChange={context.onAttachmentsChange}/><MemberChecks label="业务负责人" values={asset.owner_ids} onChange={value=>set('owner_ids',value)} context={context}/><Field label="对象访问政策"><select value={asset.policy_ref?.resolution==='RESOLVED'?`${asset.policy_ref.policy_id}@${asset.policy_ref.revision}`:''} onChange={e=>{const policy=(context.policies||[]).find(item=>`${item.policy_ref.policy_id}@${item.policy_ref.revision}`===e.target.value);set('policy_ref',policy?copy(policy.policy_ref):{policy_id:null,revision:null,resolution:'UNKNOWN'});}}><option value="">尚未确认 · 暂存草稿</option>{(context.policies||[]).map(item=><option key={`${item.policy_ref.policy_id}@${item.policy_ref.revision}`} value={`${item.policy_ref.policy_id}@${item.policy_ref.revision}`}>{item.content?.description||item.policy_ref.policy_id} · r{item.policy_ref.revision}</option>)}</select><small>保存确切政策版本；读取政策不授予数据查询执行权限。</small></Field></Section><details className="sw-more"><summary>维护职责 · 高级管理</summary><MemberChecks label="维护者记录" values={asset.steward_ids} onChange={value=>set('steward_ids',value)} context={context}/><p className="sem-form-hint">实际维护和审批权限来自治理设置中的职责分派；名单本身不会授予权限。</p></details></>;
}


function SupportedSelect({value,options,...props}){
 const known=options.some(option=>(Array.isArray(option)?option[0]:option)===value);
 return <Select {...props} value={value} options={known?options:[...options,[value,showValue(value)+'（现有定义，尚未支持）']]}/>;
}
function MetricFields({asset,onChange,context,view}){
 const spec=asset.spec,set=(key,value)=>onChange({...asset,spec:{...spec,[key]:value}}),time=spec.time_policy||{},entity=assetFor(spec.entity_ref,context);
 function useEntityGrain(){const e=entity?.asset_revision;if(!e)return;set('grain',{description:e.spec.grain,property_refs:e.spec.business_key.map(property_id=>({entity_ref:copy(spec.entity_ref),property_id}))});}
 return <>
 {(!view||view==='definition')&&<Section title="统计对象与计算口径" description="选择业务属性，计算字段会在数据实现中生成。"><AssetSelect label="统计实体 *" value={spec.entity_ref} onChange={value=>set('entity_ref',value)} context={context} types={['entity']}/><AggregateControl value={spec.expression} onChange={value=>onChange(prepareSemanticSave({...asset,spec:{...spec,expression:value}}))} kind="property" entityRef={spec.entity_ref} context={context}/><Text label="一条业务记录代表什么（粒度）" value={spec.grain?.description} onChange={value=>set('grain',{...spec.grain,description:value})}/><div className="wide"><div className="sw-section-heading"><strong className="sw-small-title">业务粒度标识</strong>{entity&&<button type="button" className="btn" onClick={useEntityGrain}>引用实体粒度与业务键</button>}</div>{(spec.grain?.property_refs||[]).map((property,index)=><div className="sw-inline-row" key={index}><PropertySelect label={`标识 ${index+1}`} value={property} entityRef={spec.entity_ref} context={context} onChange={value=>set('grain',{...spec.grain,property_refs:spec.grain.property_refs.map((old,i)=>i===index?value:old)})}/><Remove onClick={()=>set('grain',{...spec.grain,property_refs:spec.grain.property_refs.filter((_,i)=>i!==index)})}/></div>)}<button className="btn" type="button" onClick={()=>set('grain',{...spec.grain,property_refs:[...(spec.grain?.property_refs||[]),null]})}><Plus size={13}/>增加粒度标识</button><p className="sem-form-hint">引用是填写建议；请确认实体粒度确实适用于本指标。派生依赖和去重声明由计算口径生成。</p></div></Section>}
 {(!view||view==='analysis')&&<><Section title="业务时间与计量单位" description="选择真实的时间事件。当前执行使用源库时间，日期区间为开始含、结束不含。"><PropertySelect label="业务时间属性" value={time.property_ref} entityRef={spec.entity_ref} context={context} onChange={value=>set('time_policy',{...time,property_ref:value})} nullableValue/><SupportedSelect label="时间模式" value={time.kind} options={['UNKNOWN','EVENT_RANGE']} onChange={value=>set('time_policy',{...time,kind:value,...(value==='EVENT_RANGE'?{interval:'[start,end)'}:{})})}/><Text label="时区 / 源时间约定" value={time.timezone} onChange={value=>set('time_policy',{...time,timezone:value})} nullableValue help="没有依据时保持未知；指定时区转换尚未支持。"/><button type="button" className="btn sm-inline-action" onClick={()=>set('time_policy',{...time,timezone:'SOURCE'})}>确认使用源库时间（不转换）</button><SupportedSelect label="历史取值策略" value={time.history_policy} options={['UNKNOWN','CURRENT','IMMUTABLE']} onChange={value=>set('time_policy',{...time,history_policy:value})}/><div className="sm-capability"><strong>区间规则</strong><p>{time.interval==='[start,end)'?'开始包含，结束不包含':showValue(time.interval)}</p></div><div className="wide sm-unit-presets"><span>单位快捷填写</span><button type="button" className="btn" onClick={()=>set('unit',{kind:'COUNT',code:'count',currency:null,scale:1,authority:spec.unit?.kind==='COUNT'?spec.unit.authority:'UNKNOWN'})}>数量 · count</button><button type="button" className="btn" onClick={()=>set('unit',{kind:'NUMBER',code:'score',currency:null,scale:1,authority:spec.unit?.code==='score'?spec.unit.authority:'UNKNOWN'})}>评分 · score</button><small>仍需确认单位依据</small></div><UnitControl value={spec.unit} onChange={value=>set('unit',value)}/></Section><Section title="分析维度与结果解释"><AssetChecks label="允许按哪些维度分析" values={spec.allowed_dimension_refs} onChange={value=>onChange({...asset,spec:{...spec,allowed_dimension_refs:value,max_dimensions:value.length?(spec.max_dimensions||1):0}})} context={context} types={['dimension']}/><Field label="最多同时分组维度数"><input type="number" min="0" max="1" value={spec.max_dimensions??0} onChange={e=>set('max_dimensions',Number(e.target.value))}/><small>当前执行最多支持 1 个维度；现有更大值会保留，仍受执行门禁限制。</small></Field><SupportedSelect label="空值处理" value={spec.null_policy} options={['UNKNOWN','REJECT_ROW_AND_WARN','IGNORE']} onChange={value=>set('null_policy',value)}/><SupportedSelect label="空结果处理" value={spec.empty_result_policy} options={['UNKNOWN','NO_DATA']} onChange={value=>set('empty_result_policy',value)}/></Section><details className="sw-more"><summary>高级与后续能力 · 现有配置保留</summary><PreservedCapability title="默认筛选" description="当前执行器尚不支持指标默认筛选；已有条件完整保留，非空仍会阻断执行。" value={spec.default_filter}/><PreservedCapability title="可加性与维度组合" description="尚未参与重聚合或组合约束规划；需要相应执行能力后再启用维护。" value={{additivity:spec.additivity,forbidden_dimension_sets:spec.forbidden_dimension_sets}}/><JsonReadOnly value={{metric_kind:spec.metric_kind,depends_on_metric_refs:expressionReferences(spec.expression).metrics,distinct_property_refs:expressionReferences(spec.expression).distinct}} title="计算口径生成的依赖与去重声明"/></details></>}
 </>;
}

function ConditionControl({label,value,onChange,context,kind='field',entityRef,datasetRef}){const simple=value?.op==='binary'&&['=','!=','<','<=','>','>='].includes(value.operator)&&value.left?.op===kind&&value.right?.op==='literal',reference=simple?value.left[kind+'_ref']:null,set=(key,next)=>onChange({...value,[key]:next});return <div className="sw-condition wide"><strong className="sw-small-title">{label}</strong>{value===null||value===undefined?<button className="btn" type="button" onClick={()=>onChange({op:'binary',operator:'=',left:kind==='field'?{op:'field',field_ref:null}:{op:'property',property_ref:null},right:{op:'literal',value:''}})}><Plus size={13}/>添加受控条件</button>:simple?<><div className="sw-form-grid">{kind==='field'?<CatalogFieldSelect label="筛选字段" value={reference} onChange={next=>set('left',{op:'field',field_ref:next})} context={context} datasetRef={datasetRef}/>:<PropertySelect label="筛选属性" value={reference} onChange={next=>set('left',{op:'property',property_ref:next})} context={context} entityRef={entityRef}/>}<Select label="比较" value={value.operator} options={['=','!=','<','<=','>','>=']} onChange={next=>set('operator',next)}/><Select label="值类型" value={value.right.value===null?'null':typeof value.right.value} options={[["string","文本"],["number","数值"],["boolean","布尔"],["null","空值"]]} onChange={next=>set('right',{op:'literal',value:next==='number'?0:next==='boolean'?false:next==='null'?null:''})}/>{typeof value.right.value==='boolean'?<Select label="筛选值" value={String(value.right.value)} options={[["true","true"],["false","false"]]} onChange={next=>set('right',{op:'literal',value:next==='true'})}/>:value.right.value!==null&&<Field label="筛选值"><input type={typeof value.right.value==='number'?'number':'text'} value={value.right.value} onChange={e=>set('right',{op:'literal',value:typeof value.right.value==='number'?Number(e.target.value):e.target.value})}/></Field>}</div><button className="btn" type="button" onClick={()=>onChange(null)}>移除条件</button></>:<><p className="sw-expression-summary">{expressionLabel(value,context)}</p><Notice>现有条件包含组合或时间参数，原结构完整保留；本版只编辑单项比较。清除会影响计算范围。</Notice><button className="btn" type="button" onClick={()=>onChange(null)}>清除现有条件</button><JsonReadOnly value={value}/></>}</div>;}

function CatalogMigration({asset,onChange,context}){const [target,setTarget]=useState(''),[preview,setPreview]=useState(null),[error,setError]=useState('');function plan(){setError('');try{setPreview(planCatalogMigration(asset,target,context));}catch(e){setPreview(null);setError(e.message);}}function apply(){try{const current=planCatalogMigration(asset,target,context);onChange(current.asset);setPreview(null);setError('');}catch(e){setError(e.message);}}return <div className="sw-catalog-migration wide"><strong className="sw-small-title">将此映射应用到新的目录释义版本</strong><p className="sem-form-hint">显式核对同一数据源、物理表、结构指纹和字段类型后，仅迁移编辑草稿中的目录引用。名称/业务定义变化仍需人工核对；此操作不会保存或发布。</p><div className="sw-inline-row"><Field label="目标目录快照"><select value={target} onChange={e=>{setTarget(e.target.value);setPreview(null);setError('');}}><option value="">选择新目录版本</option>{context.snapshots.map(snapshot=><option key={snapshot.catalog_snapshot_id} value={snapshot.catalog_snapshot_id}>{snapshot.source_revision||'目录快照'} · {snapshot.catalog_snapshot_id.slice(-20)}</option>)}</select></Field><button type="button" className="btn" disabled={!target} onClick={plan}>核对迁移影响</button></div>{error&&<Notice>{error}</Notice>}{preview&&<><p className="sw-expression-summary">将更新 {preview.count} 处精确目录引用；{preview.oldSnapshotIds.length} 个旧快照 → 目录 {target.slice(-20)}。</p><button className="btn primary" type="button" disabled={!preview.count} onClick={apply}>确认迁移这些引用到当前草稿</button><JsonReadOnly value={preview.replacements} title="逐项核对引用变化"/></>}</div>;}

function BindingSteps({asset,onChange,context,step,setStep,existing,request}){
 const spec=asset.spec,set=(key,value)=>onChange({...asset,spec:{...spec,[key]:value}}),metric=assetFor(spec.metric_ref,context)?.asset_revision,dataset=datasetFor(spec.base_dataset_ref,context),[generationError,setGenerationError]=useState(''),[generated,setGenerated]=useState(false);
 const steps=[['选择口径','复用已定义的业务指标'],['字段与计算','属性映射后生成计算'],['维度与连接','仅跨表分析时维护'],['验证与依据','确认覆盖、责任和依据']];
 function generate(){try{onChange(deriveBindingDraft(asset,context));setGenerationError('');setGenerated(true);}catch(e){setGenerationError(e.message);setGenerated(false);}}
 return <><nav className="sw-step-nav sm-four-steps" aria-label="物理映射维护步骤">{steps.map(([title,description],index)=><button type="button" key={title} className={step===index?'active':''} onClick={()=>setStep(index)}><b>{index+1}</b><span>{title}<small>{description}</small></span></button>)}</nav>
 <div className="sw-two-sides"><div><small>业务契约</small><strong>{metric?.name||'尚未选择指标'}</strong>{metric&&<span>{expressionLabel(metric.spec.expression,context)}</span>}</div><ArrowRight size={20}/><div><small>数据实现</small><strong>{datasetLabel(spec.base_dataset_ref,context)}</strong><p>{expressionLabel(spec.calculation,context)}</p></div></div>
 {step===0&&<><BasicFields asset={asset} onChange={onChange} context={context}/><Section title="选择要实现的业务指标" description="引用已确认的计算口径；同一指标的多个实现目前需要澄清选择。"><AssetSelect label="业务指标 *" value={spec.metric_ref} onChange={value=>set('metric_ref',value)} context={context} types={['metric']}/><Text label="实现范围说明（可选）" value={spec.applicability?.description} onChange={value=>set('applicability',{...spec.applicability,description:value})} multiline help="用于人工理解，当前不会据此自动选择多条实现。"/>{metric&&<BusinessContractCard asset={metric} context={context}/>}</Section></>}
 {step===1&&<><Section title="选择数据表并映射业务属性" description="先选择实际字段，系统据此生成计算和时间映射。物理粒度仍需人工确认。"><DatasetSelect label="基础数据表与目录版本 *" value={spec.base_dataset_ref} onChange={value=>set('base_dataset_ref',value)} context={context}/>{dataset&&<div className="sw-catalog-facts"><strong>{dataset.dataset.namespace}.{dataset.dataset.physical_name}</strong><span>数据源 {dataset.dataset.datasource_id} · {showValue(dataset.dataset.constraints_state)}</span></div>}<div className="wide"><div className="sw-section-heading"><strong className="sw-small-title">业务属性 → 实际字段</strong><button className="btn" type="button" disabled={!metric} onClick={()=>onChange(completePropertyMappings(asset,metric,context))}>列出此口径需要的属性</button></div>{(spec.property_mappings||[]).map((mapping,index)=><div className="sw-array-card" key={index}><div className="sw-form-grid"><PropertySelect label="业务属性" value={mapping.property_ref} onChange={value=>set('property_mappings',spec.property_mappings.map((old,i)=>i===index?{...old,property_ref:value}:old))} context={context}/>{mapping.expression?.op==='field'?<CatalogFieldSelect label="实现字段" value={mapping.expression.field_ref} onChange={value=>set('property_mappings',spec.property_mappings.map((old,i)=>i===index?{...old,expression:{op:'field',field_ref:value}}:old))} context={context}/>:<JsonReadOnly value={mapping.expression} title="现有复杂属性映射（保留）"/>}</div><Remove onClick={()=>set('property_mappings',spec.property_mappings.filter((_,i)=>i!==index))}/></div>)}<button className="btn" type="button" onClick={()=>set('property_mappings',[...(spec.property_mappings||[]),{property_ref:null,expression:{op:'field',field_ref:null}}])}><Plus size={13}/>增加属性映射</button></div><Text label="一行物理记录代表什么 *" value={spec.physical_grain?.description} onChange={value=>set('physical_grain',{...spec.physical_grain,description:value})}/><RefFieldList label="物理粒度键（真实记录身份）" values={spec.physical_grain?.key_field_refs} onChange={value=>set('physical_grain',{...spec.physical_grain,key_field_refs:value})} context={context} datasetRef={spec.base_dataset_ref}/><div className="wide sm-generate"><button type="button" className="btn primary" disabled={!metric||!spec.base_dataset_ref} onClick={generate}>从业务属性生成计算、时间与依赖</button><p>将更新当前草稿中的物理计算和时间字段，保留已有额外依赖与约束；不修改物理粒度、权限或审批。</p>{generationError&&<Notice>{generationError}</Notice>}{generated&&<p role="status" className="sm-success">已生成当前映射，请核对下面的计算摘要。保存后仍需服务端诊断。</p>}<p className="sw-expression-summary">计算：{expressionLabel(spec.calculation,context)}<br/>时间：{fieldLabel(spec.time_field_ref,context)}</p></div></Section><details className="sw-more"><summary>目录迁移与现有执行配置 · 高级维护</summary><CatalogMigration asset={asset} onChange={onChange} context={context}/><div className="sw-form-grid"><AggregateControl value={spec.calculation} onChange={value=>set('calculation',value)} kind="field" context={context}/><CatalogFieldSelect label="明确调整时间字段" value={spec.time_field_ref} onChange={value=>set('time_field_ref',value)} context={context} nullableValue/><PreservedCapability title="固定参数与基础筛选" description="当前仅支持时间起止参数；默认筛选尚未执行，非空会阻断。已有配置保持原样。" value={{parameter_bindings:spec.parameter_bindings,base_filter:spec.base_filter,scope_filter:spec.applicability?.scope_filter}}/></div></details></>}
 {step===2&&<><Section title="按需添加分析维度" description="同表分析无需连接。字段依赖由表达式生成；跨表路径必须可解析。">{(spec.dimension_implementations||[]).map((impl,index)=><div className="sw-array-card wide" key={index}><div className="sw-form-grid"><AssetSelect label="分析维度" value={impl.dimension_ref} onChange={value=>set('dimension_implementations',spec.dimension_implementations.map((old,i)=>i===index?{...old,dimension_ref:value}:old))} context={{...context,assets:context.assets.filter(item=>item.asset_revision.asset_type!=='dimension'||metric?.spec.allowed_dimension_refs?.some(ref=>sameAsset(ref,item.asset_ref)))}} types={['dimension']}/>{impl.expression?.op==='field'?<CatalogFieldSelect label="实际分组字段" value={impl.expression.field_ref} onChange={value=>set('dimension_implementations',spec.dimension_implementations.map((old,i)=>i===index?{...old,expression:{op:'field',field_ref:value}}:old))} context={context}/>:<JsonReadOnly value={impl.expression}/>}<details className="sw-more"><summary>连接作用域与已有字段依赖</summary><JoinChecks label="该维度需要的连接" values={impl.required_join_ids} joins={spec.joins} onChange={value=>set('dimension_implementations',spec.dimension_implementations.map((old,i)=>i===index?{...old,required_join_ids:value}:old))}/><JsonReadOnly value={impl.required_field_refs} title="现有额外字段依赖（保存时自动补齐表达式字段）"/></details></div><Remove onClick={()=>set('dimension_implementations',spec.dimension_implementations.filter((_,i)=>i!==index))}/></div>)}<button className="btn" type="button" disabled={!metric} onClick={()=>set('dimension_implementations',[...(spec.dimension_implementations||[]),{dimension_ref:null,expression:{op:'field',field_ref:null},required_join_ids:[],required_field_refs:[]}])}><Plus size={13}/>增加维度实现</button></Section><details className="sw-more" open={spec.joins.length?true:undefined}><summary>跨表连接 · {spec.joins.length?spec.joins.length+' 条路径':'同表可跳过'}</summary><Section title="连接路径与防膨胀规则" description="保留逻辑关系、键、基数、空键及等价依据；未知语义不会自动批准。"><JoinChecks label="基础计算必须执行的连接" values={spec.base_join_ids} joins={spec.joins} onChange={value=>set('base_join_ids',value)}/>{(spec.joins||[]).map((join,index)=><JoinEditor key={index} value={join} context={context} onChange={value=>set('joins',spec.joins.map((old,i)=>i===index?value:old))} onRemove={()=>set('joins',spec.joins.filter((_,i)=>i!==index))}/>)}<button className="btn" type="button" onClick={()=>set('joins',[...(spec.joins||[]),{join_id:'join_'+crypto.randomUUID().slice(0,8),logical_relation_ref:null,from_dataset_ref:copy(spec.base_dataset_ref),to_dataset_ref:null,key_pairs:[],join_type:'INNER',expected_cardinality:'UNKNOWN',fanout_strategy:'REJECT',allocation_rule_ref:null,null_key_policy:'UNKNOWN',temporal_condition:null,equivalence_evidence_refs:[]}])}><Plus size={13}/>增加连接路径</button></Section></details><button type="button" className="btn" onClick={generate}>按已选属性映射更新维度计算与依赖</button>{generationError&&<Notice>{generationError}</Notice>}</>}
 {step===3&&<>{existing&&request&&<ImplementationDiagnostic key={existing.asset_ref.asset_id+'@'+existing.asset_ref.revision} asset={existing.asset_revision} request={request}/>}<VerificationRules/><details className="sw-more"><summary>覆盖范围声明 · 有依据时维护</summary><p className="sem-form-hint">未知时保持为空。源库观测时间范围不等于业务数据完整。</p><div className="sw-form-grid"><Text label="覆盖开始（ISO 8601，含时区）" value={spec.coverage?.start} onChange={value=>set('coverage',{...spec.coverage,start:value})} nullableValue/><Text label="覆盖结束（不含）" value={spec.coverage?.end_exclusive} onChange={value=>set('coverage',{...spec.coverage,end_exclusive:value})} nullableValue/><Text label="数据截至时点" value={spec.coverage?.data_as_of} onChange={value=>set('coverage',{...spec.coverage,data_as_of:value})} nullableValue/><AssetChecks label="覆盖范围证据" values={spec.coverage?.evidence_refs} onChange={value=>set('coverage',{...spec.coverage,evidence_refs:value})} context={context} types={['evidence']}/></div></details><details className="sw-more"><summary>保留的后续能力配置</summary><PreservedCapability title="新鲜度 SLA、分区和核验要求声明" description="Binding SLA 尚未支持，非空仍阻断；分区字段未驱动裁剪，旧核验项目列表不调度检查。真实检查由服务端决定。" value={{freshness_sla_minutes:spec.freshness_sla_minutes,partition_field_refs:spec.partition_field_refs,verification_rule_ids:spec.verification_rule_ids}}/></details><ResponsibilityFields asset={asset} onChange={onChange} context={context}/><MaintenanceChecklist asset={asset} context={context}/></>}
 <div className="sw-step-footer"><button type="button" className="btn" disabled={step===0} onClick={()=>setStep(step-1)}><ChevronLeft size={14}/>上一步</button><span>第 {step+1} 步，共 4 步 · 修改留在当前草稿</span><button type="button" className="btn primary" disabled={step===3} onClick={()=>setStep(step+1)}>下一步<ChevronRight size={14}/></button></div></>;
}


function VerificationRules(){return <Section title="保存后实际运行的检查" description="检查由资产类型和服务端能力决定，无需重复勾选；这里不表示已经通过。"><div className="wide sm-check-tags">{['类型与确切引用','真实 Owner 与对象政策','来源与业务有效期','逻辑/物理映射编译','覆盖声明与连接依据'].map(title=><span key={title}><CheckCircle2 size={14}/>{title}</span>)}</div><p className="sem-form-hint wide">机器核验检查定义与映射；源库真实权限、粒度、覆盖、JOIN 与数据批次门禁在执行前另行检查。保存不会自动核验或批准。</p></Section>;}

function JoinChecks({label,values=[],joins=[],onChange}){return <fieldset className="sw-check-field wide"><legend>{label}</legend><div className="sw-check-grid">{joins.map(join=><label key={join.join_id}><input type="checkbox" checked={values.includes(join.join_id)} onChange={e=>onChange(e.target.checked?[...values,join.join_id]:values.filter(id=>id!==join.join_id))}/>{join.join_id}</label>)}</div>{!joins.length&&<p className="sem-form-hint">没有连接路径；同表字段可不需要连接。</p>}</fieldset>;}
function JoinEditor({value:join,onChange,onRemove,context}){const set=(key,value)=>onChange({...join,[key]:value});return <div className="sw-array-card wide"><div className="sw-card-heading"><strong>连接路径 {join.join_id}</strong><Remove onClick={onRemove}/></div><div className="sw-form-grid"><AssetSelect label="对应业务关系" value={join.logical_relation_ref} onChange={value=>set('logical_relation_ref',value)} context={context} types={['relation']}/><Select label="关联方式" value={join.join_type} options={[["INNER","仅匹配记录（INNER）"],["LEFT","保留左侧记录（LEFT）"]]} onChange={value=>set('join_type',value)}/><DatasetSelect label="起始表" value={join.from_dataset_ref} onChange={value=>set('from_dataset_ref',value)} context={context}/><DatasetSelect label="目标表" value={join.to_dataset_ref} onChange={value=>set('to_dataset_ref',value)} context={context}/>{join.key_pairs.map((pair,index)=><div className="sw-inline-row wide" key={index}><CatalogFieldSelect label={`起始键 ${index+1}`} value={pair.from} onChange={value=>set('key_pairs',join.key_pairs.map((old,i)=>i===index?{...old,from:value}:old))} datasetRef={join.from_dataset_ref} context={context}/><ArrowRight size={15}/><CatalogFieldSelect label={`目标键 ${index+1}`} value={pair.to} onChange={value=>set('key_pairs',join.key_pairs.map((old,i)=>i===index?{...old,to:value}:old))} datasetRef={join.to_dataset_ref} context={context}/><Remove onClick={()=>set('key_pairs',join.key_pairs.filter((_,i)=>i!==index))}/></div>)}<button className="btn" type="button" onClick={()=>set('key_pairs',[...join.key_pairs,{from:null,to:null}])}><Plus size={13}/>增加连接键对</button><SupportedSelect label="预期基数" value={join.expected_cardinality} options={['UNKNOWN','1:1','N:1']} onChange={value=>set('expected_cardinality',value)}/><SupportedSelect label="防膨胀策略" value={join.fanout_strategy} options={[["REJECT","检测膨胀即拒绝"],"UNKNOWN"]} onChange={value=>set('fanout_strategy',value)}/><Select label="空连接键" value={join.null_key_policy} options={['UNKNOWN',['DROP','舍弃'],['KEEP','保留'],['ERROR','阻止执行']]} onChange={value=>set('null_key_policy',value)}/><AssetChecks label="物理等价 / 连接证明" values={join.equivalence_evidence_refs} onChange={value=>set('equivalence_evidence_refs',value)} context={context} types={['evidence']}/>{(join.temporal_condition||join.allocation_rule_ref)&&<JsonReadOnly value={{temporal_condition:join.temporal_condition,allocation_rule_ref:join.allocation_rule_ref}} title="现有时间条件与分摊规则（保留只读）"/>}</div></div>;}

function EntityFields({asset,onChange}){const spec=asset.spec,set=(key,value)=>onChange({...asset,spec:{...spec,[key]:value}});return <Section title="业务实体与属性" description="业务主键与数据库主键分别维护。属性编码创建后尽量保持稳定，名称可独立修订。"><Select label="对象类型" value={spec.kind} options={[["ENTITY","业务实体"],["EVENT","业务事件"]]} onChange={value=>set('kind',value)}/><Text label="实体粒度" value={spec.grain} onChange={value=>set('grain',value)}/><fieldset className="sw-check-field wide"><legend>业务标识（可选择组合）</legend><div className="sw-check-grid">{spec.properties.map(property=><label key={property.property_id}><input type="checkbox" checked={spec.business_key.includes(property.property_id)} onChange={e=>set('business_key',e.target.checked?[...spec.business_key,property.property_id]:spec.business_key.filter(id=>id!==property.property_id))}/>{property.name||'未命名属性'}</label>)}</div></fieldset>{spec.properties.map((property,index)=><div className="sw-array-card wide" key={index}><div className="sw-form-grid"><Text label="属性中文名" value={property.name} onChange={value=>set('properties',spec.properties.map((old,i)=>i===index?{...old,name:value}:old))}/><Text label="属性稳定编码" value={property.property_id} onChange={value=>set('properties',spec.properties.map((old,i)=>i===index?{...old,property_id:value}:old))}/><Text label="逻辑数据类型" value={property.data_type} onChange={value=>set('properties',spec.properties.map((old,i)=>i===index?{...old,data_type:value}:old))}/><Select label="语义角色" value={property.semantic_role} options={['IDENTIFIER','ATTRIBUTE','MEASURE','STATUS','EVENT_TIME','SNAPSHOT_DATE','BUSINESS_DATE','PROCESSING_TIME']} onChange={value=>set('properties',spec.properties.map((old,i)=>i===index?{...old,semantic_role:value}:old))}/><Select label="是否可空" value={property.nullable===null?'UNKNOWN':String(property.nullable)} options={['UNKNOWN',['true','允许空值'],['false','禁止空值']]} onChange={value=>set('properties',spec.properties.map((old,i)=>i===index?{...old,nullable:value==='UNKNOWN'?null:value==='true'}:old))}/>{property.unit&&<UnitControl value={property.unit} onChange={value=>set('properties',spec.properties.map((old,i)=>i===index?{...old,unit:value}:old))}/>}</div><Remove onClick={()=>set('properties',spec.properties.filter((_,i)=>i!==index))}/></div>)}<button className="btn" type="button" onClick={()=>set('properties',[...spec.properties,{property_id:'',name:'',data_type:'STRING',semantic_role:'ATTRIBUTE',nullable:null,unit:null}])}><Plus size={13}/>添加业务属性</button></Section>;}

function DimensionFields({asset,onChange,context}){const spec=asset.spec,set=(key,value)=>onChange({...asset,spec:{...spec,[key]:value}});return <><Section title="分析含义与分组规则" description="定义按什么属性分析。实际分组字段由指标的数据实现维护。"><AssetSelect label="所属业务实体" value={spec.entity_ref} context={context} types={['entity']} onChange={value=>set('entity_ref',value)}/><PropertySelect label="分析属性" value={{entity_ref:spec.entity_ref,property_id:spec.property_id}} entityRef={spec.entity_ref} context={context} onChange={value=>set('property_id',value?.property_id||'')}/><Text label="取值逻辑类型" value={spec.value_type} onChange={value=>set('value_type',value)}/><SupportedSelect label="空值分组规则" value={spec.null_member} options={['UNKNOWN','ERROR']} onChange={value=>set('null_member',value)}/><SupportedSelect label="历史取值策略" value={spec.history_policy} options={['UNKNOWN','CURRENT']} onChange={value=>set('history_policy',value)}/></Section><details className="sw-more"><summary>值域与层级 · 后续能力记录</summary><PreservedCapability title="值域字典与父维度" description="当前没有自动值编码转换和层级下钻。已有引用保留并继续参与引用校验。" value={{value_dictionary_ref:spec.value_dictionary_ref,parent_dimension_refs:spec.parent_dimension_refs}}/></details></>;}

function OtherBusinessFields({asset,onChange,context}){const spec=asset.spec,set=(key,value)=>onChange({...asset,spec:{...spec,[key]:value}});if(asset.asset_type==='domain')return <Section title="业务域边界"><AssetSelect label="父业务域" value={spec.parent_ref} onChange={value=>set('parent_ref',value)} context={context} types={['domain']} nullableValue/><Text label="纳入 / 排除的业务过程" value={spec.scope_notes} onChange={value=>set('scope_notes',value)} multiline/></Section>;if(asset.asset_type==='term')return <Section title="术语含义与歧义"><Select label="与引用概念的关系" value={spec.target_relation} options={['EQUIVALENT','BROADER','NARROWER','RELATED','AMBIGUOUS']} onChange={value=>set('target_relation',value)}/><AssetChecks label="关联的业务概念" values={spec.target_refs} onChange={value=>set('target_refs',value)} context={context} types={['metric','dimension','entity','term','relation','domain']}/><StringList label="明确排除的含义（一行一项）" values={spec.excluded_meanings} onChange={value=>set('excluded_meanings',value)}/></Section>;return <Section title="业务关系与逻辑连接键"><AssetSelect label="起始业务实体" value={spec.from_entity_ref} onChange={value=>set('from_entity_ref',value)} context={context} types={['entity']}/><AssetSelect label="目标业务实体" value={spec.to_entity_ref} onChange={value=>set('to_entity_ref',value)} context={context} types={['entity']}/><Text label="关系含义" value={spec.predicate} onChange={value=>set('predicate',value)}/><Text label="起始角色" value={spec.from_role} onChange={value=>set('from_role',value)}/><Text label="目标角色" value={spec.to_role} onChange={value=>set('to_role',value)}/><Select label="业务基数" value={spec.cardinality} options={['UNKNOWN','1:1','1:N','N:1','N:M']} onChange={value=>set('cardinality',value)}/>{spec.logical_key_pairs.map((pair,index)=><div className="sw-inline-row wide" key={index}><PropertySelect label={`起始业务键 ${index+1}`} value={pair.from} context={context} entityRef={spec.from_entity_ref} onChange={value=>set('logical_key_pairs',spec.logical_key_pairs.map((old,i)=>i===index?{...old,from:value}:old))}/><PropertySelect label={`目标业务键 ${index+1}`} value={pair.to} context={context} entityRef={spec.to_entity_ref} onChange={value=>set('logical_key_pairs',spec.logical_key_pairs.map((old,i)=>i===index?{...old,to:value}:old))}/><Remove onClick={()=>set('logical_key_pairs',spec.logical_key_pairs.filter((_,i)=>i!==index))}/></div>)}<button type="button" className="btn" onClick={()=>set('logical_key_pairs',[...spec.logical_key_pairs,{from:null,to:null}])}><Plus size={13}/>增加业务连接键</button></Section>;}

function SourceFields({asset,onChange,onSourceText}){const spec=asset.spec,set=(key,value)=>onChange({...asset,spec:{...spec,[key]:value}}),[raw,setRaw]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function bindRaw(){setBusy(true);setError('');try{const inspected=await inspectSourceText(raw,'');set('content_sha256',inspected.contentHash);onSourceText?.(raw);}catch(e){setError(e.message);}finally{setBusy(false);}}return <><Section title="来源定位与版本" description="原文版本、内容摘要与可回查位置共同固定来源。原文变化需创建新修订。"><Select label="来源类别" value={spec.source_kind} options={['BUSINESS_SPEC','CATALOG','SQL','TECHNICAL_QA','FEEDBACK']} onChange={value=>set('source_kind',value)}/><Text label="原文位置 / URI" value={spec.uri} onChange={value=>set('uri',value)}/><Text label="材料版本" value={spec.source_revision} onChange={value=>set('source_revision',value)}/><Select label="敏感级别" value={spec.classification} options={['PUBLIC','INTERNAL','SENSITIVE']} onChange={value=>set('classification',value)}/><Select label="材料权威性声明" value={spec.authority} options={['UNREVIEWED','TECHNICAL_ONLY','BUSINESS_APPROVED']} onChange={value=>set('authority',value)} help="这里只保存声明；服务端仍检查真实业务审批。"/><div className="wide sw-identity"><strong>原文 SHA-256</strong><code>{spec.content_sha256||'尚未绑定原文'}</code></div></Section><Section title="上传 / 粘贴来源原文" description="本地归档支持 UTF-8 JSON，按原始字节校验，不改换行或空格。选择绑定后，保存新修订再归档。"><Field label="选择 JSON 文件"><input type="file" accept=".json,application/json" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;try{setRaw(decodeSourceFile(await file.arrayBuffer()));setError('');onSourceText?.(null);}catch(err){setError(err.message);}}}/></Field><Field label="或粘贴完整 JSON 原文" wide><textarea rows={7} value={raw} onChange={e=>{setRaw(e.target.value);onSourceText?.(null);}} spellCheck={false}/></Field><button type="button" className="btn" disabled={busy||!raw.trim()} onClick={bindRaw}>校验并绑定这份原文</button>{error&&<Notice>{error}</Notice>}</Section></>;}
function EvidenceFields({asset,onChange,context}){const spec=asset.spec,set=(key,value)=>onChange({...asset,spec:{...spec,[key]:value}});if(asset.asset_type==='claim')return <Section title="可单独审核的业务主张"><AssetSelect label="主张对象" value={spec.subject_ref} onChange={value=>set('subject_ref',value)} context={context}/><Select label="主张类别" value={spec.claim_kind} options={['BUSINESS_DEFINITION','MAPPING_ASSERTION','TECHNICAL_OBSERVATION']} onChange={value=>set('claim_kind',value)}/><Text label="主张内容" value={spec.statement} onChange={value=>set('statement',value)} multiline/>{spec.evidence_links.map((link,index)=><div className="sw-inline-row wide" key={index}><AssetSelect label="证据" value={link.evidence_ref} onChange={value=>set('evidence_links',spec.evidence_links.map((old,i)=>i===index?{...old,evidence_ref:value}:old))} context={context} types={['evidence']}/><Select label="证据立场" value={link.stance} options={['SUPPORT','REFUTE']} onChange={value=>set('evidence_links',spec.evidence_links.map((old,i)=>i===index?{...old,stance:value}:old))}/><Remove onClick={()=>set('evidence_links',spec.evidence_links.filter((_,i)=>i!==index))}/></div>)}<button className="btn" type="button" onClick={()=>set('evidence_links',[...spec.evidence_links,{evidence_ref:null,stance:'SUPPORT'}])}><Plus size={13}/>添加证据</button><PreservedCapability title="主张适用条件" description="当前只记录主张，不对条件求值。现有条件保持完整，冲突仍需人工裁决。" value={spec.condition}/></Section>;return <Section title="证据片段与可回源定位"><AssetSelect label="原始来源" value={spec.source_ref} onChange={value=>set('source_ref',value)} context={context} types={['source']}/><Select label="证据类型" value={spec.evidence_kind} options={['BUSINESS_TEXT','TECHNICAL_QA','SQL_LINEAGE','CATALOG_OBSERVATION']} onChange={value=>set('evidence_kind',value)}/><Text label="JSON Pointer 定位" value={spec.locator?.pointer} onChange={value=>set('locator',{kind:'JSON_POINTER',pointer:value})} help="例如 /metrics/0；应指向已归档原文中的实际片段。"/><Text label="观测时间（含时区）" value={spec.observed_at} onChange={value=>set('observed_at',value)} nullableValue/><Text label="原文摘录" value={spec.excerpt} onChange={value=>set('excerpt',value)} multiline/><Text label="证据支持的断言" value={spec.assertion} onChange={value=>set('assertion',value)} multiline/><div className="sm-capability"><strong>摘录校验</strong><p>保存时自动计算摘要。来源版本、原文定位和片段一致性仍由服务端核验。</p></div></Section>;}

export function MaintenanceChecklist({asset,context}){const issues=maintenanceIssues(asset,context);return <div className="sw-checklist wide"><strong>维护缺项提示</strong><p>以下为当前表单的可解析性提示；真实核验与审批结果以服务端记录为准。</p>{issues.length?<ul>{issues.map(issue=><li key={issue}><AlertTriangle size={13}/>{issue}</li>)}</ul>:<p>基础填写项已齐备，仍需运行机器核验与业务审核。</p>}</div>;}
export function ImplementationDiagnostic({asset,request}){const [result,setResult]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState('');async function check(){setBusy(true);setError('');try{const response=await request(`/semantic/assets/${encodeURIComponent(asset.asset_id)}/implementation?revision=${asset.revision}`);setResult(response.data??response);}catch(e){setError(e.message);setResult(null);}finally{setBusy(false);}}return <Section title="已保存物理映射诊断" description="仅诊断此精确修订能否编译；不执行数据查询，不创建审批。未保存表单需先保存新修订。"><button className="btn" disabled={busy} onClick={check}>{busy?'诊断中…':'检查本修订的真实执行结构'}</button>{error&&<Notice>{error}</Notice>}{result&&<><div className="wide table-scroll"><table><thead><tr><th>检查项</th><th>结果</th><th>说明</th></tr></thead><tbody>{(result.checks||[]).map((check,index)=><tr key={index}><td>{check.rule_id}</td><td>{({PASS:'通过',FAIL:'失败',UNKNOWN:'尚未确认',NOT_APPLICABLE:'不适用'})[check.outcome]||check.outcome}</td><td>{check.reason}</td></tr>)}</tbody></table></div><Notice>业务批准：{String(result.business_approved)}；已检查实时源库：{String(result.live_source_checked)}。诊断成功仍需发布/索引快照和每次查询门禁。</Notice>{result.compiled_contract&&<JsonReadOnly value={result.compiled_contract} title="诊断产生的执行契约（只读）"/>}</>}</Section>;}

export function SemanticEditor({asset,onChange,context,onSourceText,existing,request}){
 const [step,setStep]=useState(0),[metricTab,setMetricTab]=useState('definition');
 const problems=semanticSaveProblems(asset),tabs=[['definition','1. 定义与口径'],['analysis','2. 时间与分析'],['evidence','3. 依据与责任']];
 return <div className="sw-editor"><div className="sm-editor-heading"><span>{typeTitles[asset.asset_type]} · {existing?'基于 r'+existing.asset_ref.revision+' 创建新修订':'新建草稿'}</span><small>保存不改变已发布版本</small></div>
 {asset.asset_type==='metric'?<><nav className="sm-editor-tabs" aria-label="指标维护步骤">{tabs.map(([id,title])=><button type="button" key={id} className={metricTab===id?'active':''} onClick={()=>setMetricTab(id)}>{title}</button>)}</nav>{metricTab==='definition'&&<BasicFields asset={asset} onChange={onChange} context={context}/>}<MetricFields asset={asset} onChange={onChange} context={context} view={metricTab}/>{metricTab==='evidence'&&<><ResponsibilityFields asset={asset} onChange={onChange} context={context}/><MaintenanceChecklist asset={asset} context={context}/></>}<div className="sw-step-footer"><button type="button" className="btn" disabled={metricTab==='definition'} onClick={()=>setMetricTab(metricTab==='evidence'?'analysis':'definition')}><ChevronLeft size={14}/>上一步</button><span>按需切换，编辑内容会保留</span><button type="button" className="btn primary" disabled={metricTab==='evidence'} onClick={()=>setMetricTab(metricTab==='definition'?'analysis':'evidence')}>下一步<ChevronRight size={14}/></button></div></>:asset.asset_type==='binding'?<BindingSteps asset={asset} onChange={onChange} context={context} step={step} setStep={setStep} existing={existing} request={request}/>:<><BasicFields asset={asset} onChange={onChange} context={context}/>{asset.asset_type==='entity'?<EntityFields asset={asset} onChange={onChange}/>:asset.asset_type==='dimension'?<DimensionFields asset={asset} onChange={onChange} context={context}/>:asset.asset_type==='source'?<SourceFields asset={asset} onChange={onChange} onSourceText={onSourceText}/>:['claim','evidence'].includes(asset.asset_type)?<EvidenceFields asset={asset} onChange={onChange} context={context}/>:<OtherBusinessFields asset={asset} onChange={onChange} context={context}/>}<ResponsibilityFields asset={asset} onChange={onChange} context={context}/></>}
 {problems.length>0&&<div className="sm-next-actions" role="status"><strong>保存前待补充</strong><span>{problems.slice(0,3).join('；')}{problems.length>3?'，另有 '+(problems.length-3)+' 项':''}</span></div>}
 <details className="sw-technical"><summary>系统身份与保存前提示{problems.length?' · '+problems.length+' 项待补充':''}</summary><div className="sw-identity"><code>{asset.asset_id}</code><span>空间 {asset.workspace_id} · 修订由服务端确认</span></div>{problems.length>0&&<ul>{problems.map(problem=><li key={problem}>{problem}</li>)}</ul>}<JsonReadOnly value={prepareSemanticSave(asset)} title="查看即将提交的结构化修订（只读）"/></details></div>;
}

export function BusinessContractCard({asset,context}){const spec=asset.spec||{};return <div className="sw-contract-card wide"><div className="sw-card-heading"><strong>{asset.name}</strong><small>r{asset.revision} · 业务契约</small></div><p>{asset.definition}</p><dl><div><dt>计算口径</dt><dd>{expressionLabel(spec.expression,context)}</dd></div><div><dt>统计实体</dt><dd>{assetLabel(spec.entity_ref,context)}</dd></div><div><dt>业务粒度</dt><dd>{spec.grain?.description||'未维护'}</dd></div><div><dt>业务时间</dt><dd>{showValue(spec.time_policy?.kind)} · {propertyLabel(spec.time_policy?.property_ref,context)}</dd></div><div><dt>时区 / 区间</dt><dd>{showValue(spec.time_policy?.timezone)} · {spec.time_policy?.interval||'未确认'}</dd></div><div><dt>单位</dt><dd>{showValue(spec.unit?.kind)} · {spec.unit?.currency||spec.unit?.code||'编码未确认'} · {showValue(spec.unit?.authority)}</dd></div><div><dt>允许维度</dt><dd>{(spec.allowed_dimension_refs||[]).map(ref=>assetLabel(ref,context)).join('、')||'未声明'}</dd></div></dl></div>;}

export function SemanticDefinition({asset,context,onOpen,onNewBinding}){const spec=asset.spec||{},bindings=(context.currentAssets||context.assets||[]).filter(item=>item.asset_revision.asset_type==='binding'&&sameAsset(item.asset_revision.spec.metric_ref,refOf(asset))),implementations=(context.currentAssets||context.assets||[]).filter(item=>item.asset_revision.asset_type==='binding').flatMap(item=>(item.asset_revision.spec.dimension_implementations||[]).filter(dimension=>sameAsset(dimension.dimension_ref,refOf(asset))).map(dimension=>({item,dimension})));return <div className="sw-definition"><p className="sw-definition-lead">{asset.definition}</p>{asset.asset_type==='metric'?<><BusinessContractCard asset={asset} context={context}/><div className="sw-section-heading"><h3>物理实现（{bindings.length}）</h3>{onNewBinding&&<button className="btn primary" onClick={()=>onNewBinding(asset)}><Plus size={13}/>为此指标创建物理映射</button>}</div>{bindings.map(item=><button className="sw-binding-link" key={exactRefKey(item.asset_ref)} onClick={()=>onOpen(item)}><GitBranch size={17}/><span><strong>{item.asset_revision.name}</strong><small>{datasetLabel(item.asset_revision.spec.base_dataset_ref,context)}</small><small>{expressionLabel(item.asset_revision.spec.calculation,context)}</small></span><ChevronRight size={16}/></button>)}{!bindings.length&&<Notice>尚无物理实现。只有业务指标定义不能直接取数。</Notice>}</>:asset.asset_type==='binding'?<><BusinessContractCard asset={assetFor(spec.metric_ref,context)?.asset_revision||{name:'指标引用不可用',spec:{}}} context={context}/><Section title="物理实现与字段对应"><div className="sw-fact"><span>基础数据表</span><strong>{datasetLabel(spec.base_dataset_ref,context)}</strong></div><div className="sw-fact"><span>实际计算</span><strong>{expressionLabel(spec.calculation,context)}</strong></div><div className="sw-fact"><span>时间字段</span><strong>{fieldLabel(spec.time_field_ref,context)}</strong></div><div className="sw-fact"><span>物理粒度</span><strong>{spec.physical_grain?.description}</strong></div><div className="wide table-scroll"><table><thead><tr><th>业务属性</th><th>目录字段实现</th><th>字段释义</th></tr></thead><tbody>{spec.property_mappings?.map((mapping,index)=><tr key={index}><td>{propertyLabel(mapping.property_ref,context)}</td><td>{expressionLabel(mapping.expression,context)}</td><td>{mapping.expression?.op==='field'?fieldFor(mapping.expression.field_ref,context)?.field.business_definition?.definition||'未维护':'复杂计算'}</td></tr>)}</tbody></table></div><div className="wide table-scroll"><table><thead><tr><th>当前映射允许维度</th><th>实际分组字段</th><th>所需连接</th></tr></thead><tbody>{spec.dimension_implementations?.map((dimension,index)=><tr key={index}><td>{assetLabel(dimension.dimension_ref,context)}</td><td>{expressionLabel(dimension.expression,context)}</td><td>{dimension.required_join_ids.join('、')||'同表，无连接'}</td></tr>)}</tbody></table></div></Section></>:asset.asset_type==='entity'?<Section title="业务实体属性"><div className="sw-fact"><span>粒度</span><strong>{spec.grain}</strong></div><div className="sw-fact"><span>业务标识</span><strong>{spec.business_key?.map(id=>spec.properties.find(property=>property.property_id===id)?.name||id).join('、')}</strong></div><div className="wide table-scroll"><table><thead><tr><th>属性名称</th><th>编码</th><th>类型</th><th>含义角色</th><th>可空</th></tr></thead><tbody>{spec.properties.map(property=><tr key={property.property_id}><td>{property.name}</td><td><code>{property.property_id}</code></td><td>{property.data_type}</td><td>{showValue(property.semantic_role)}</td><td>{property.nullable===null?'未确认':String(property.nullable)}</td></tr>)}</tbody></table></div></Section>:asset.asset_type==='dimension'?<><Section title="分析维度语义"><div className="sw-fact"><span>业务属性</span><strong>{propertyLabel({entity_ref:spec.entity_ref,property_id:spec.property_id},context)}</strong></div><div className="sw-fact"><span>空值规则</span><strong>{showValue(spec.null_member)}</strong></div><div className="sw-fact"><span>值域依据</span><strong>{spec.value_dictionary_ref?assetLabel(spec.value_dictionary_ref,context):'值域来源未维护'}</strong></div></Section><h3>物理实现中的真实字段</h3>{implementations.map(({item,dimension},index)=><button className="sw-binding-link" key={index} onClick={()=>onOpen(item)}><span><strong>{item.asset_revision.name}</strong><small>{expressionLabel(dimension.expression,context)}</small><small>{dimension.expression?.op==='field'?fieldFor(dimension.expression.field_ref,context)?.field.business_definition?.definition:'复杂表达式'}</small></span><ChevronRight size={16}/></button>)}</>:<Section title={typeTitles[asset.asset_type]+'内容'}>{Object.entries(spec).filter(([,value])=>value===null||typeof value!=='object').map(([key,value])=><div className="sw-fact" key={key}><span>{({source_kind:'来源类别',uri:'回查位置',source_revision:'材料版本',authority:'权威性',classification:'敏感级别',statement:'主张内容',excerpt:'原文片段',assertion:'证据断言',scope_notes:'业务边界',predicate:'关系含义',cardinality:'业务基数',target_relation:'概念关系'})[key]||key}</span><strong>{showValue(value)}</strong></div>)}</Section>}<MaintenanceChecklist asset={asset} context={context}/><JsonReadOnly value={asset}/></div>;}

export function CatalogBrowser({context,command,onChanged,notify}){
 const [snapshotId,setSnapshotId]=useState(''),[datasetId,setDatasetId]=useState(''),[query,setQuery]=useState(''),[editing,setEditing]=useState(null),[reason,setReason]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const snapshots=context.snapshots||[],selectedSnapshot=snapshots.find(snapshot=>snapshot.catalog_snapshot_id===snapshotId)||snapshots[0],datasets=selectedSnapshot?.datasets||[],dataset=datasets.find(item=>`${item.datasource_id}|${item.dataset_id}`===datasetId)||datasets[0];
 const fields=(dataset?.fields||[]).filter(field=>`${field.field_id} ${field.business_definition?.name_zh||''} ${field.business_definition?.definition||''}`.toLowerCase().includes(query.toLowerCase()));
 async function save(){if(!editing||!reason.trim())return;setBusy(true);setError('');try{const result=await command(`/catalog-snapshots/${encodeURIComponent(selectedSnapshot.catalog_snapshot_id)}/revisions`,{base_content_hash:selectedSnapshot.content_hash,reason,field_updates:[{dataset_id:dataset.dataset_id,datasource_id:dataset.datasource_id,field_id:editing.field_id,business_definition:{name_zh:editing.name_zh,definition:editing.definition},semantic_role:editing.semantic_role,unit:editing.unit,classification:editing.classification}]});const value=result.data??result;setEditing(null);setReason('');notify?.('字段释义已保存到新目录快照，现有映射保持原版本');await onChanged?.();if(value.catalog_snapshot?.catalog_snapshot_id)setSnapshotId(value.catalog_snapshot.catalog_snapshot_id);}catch(e){setError(e.message);}finally{setBusy(false);}}
 return <div className="sw-catalog"><div className="sw-catalog-controls"><Field label="目录快照"><select value={selectedSnapshot?.catalog_snapshot_id||''} onChange={e=>{setSnapshotId(e.target.value);setDatasetId('');setEditing(null);}}>{snapshots.map(snapshot=><option key={snapshot.catalog_snapshot_id} value={snapshot.catalog_snapshot_id}>{snapshot.source_revision||'采集版本未提供'} · {snapshot.catalog_snapshot_id.slice(-20)}</option>)}</select></Field><Field label="数据表"><select value={dataset?`${dataset.datasource_id}|${dataset.dataset_id}`:''} onChange={e=>{setDatasetId(e.target.value);setEditing(null);}}>{datasets.map(item=><option key={`${item.datasource_id}|${item.dataset_id}`} value={`${item.datasource_id}|${item.dataset_id}`}>{item.business_definition?.name_zh||item.logical_locator} · {item.namespace}.{item.physical_name}</option>)}</select></Field><Field label="搜索字段 / 中文释义"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="按字段名、中文名或定义筛选"/></Field></div>
  {error&&<Notice>{error}</Notice>}{dataset?<><div className="sw-catalog-banner"><Database size={20}/><div><strong>{dataset.logical_locator}</strong><p>实际位置 {dataset.namespace}.{dataset.physical_name} · 数据源 {dataset.datasource_id} · 约束 {showValue(dataset.constraints_state)}</p><small>字段物理名、类型与结构指纹来自采集，不能在释义编辑中改写。</small></div></div><div className="table-scroll"><table><thead><tr><th>字段 / 物理类型</th><th>中文名称</th><th>业务释义</th><th>语义角色</th><th>是否可空</th><th/></tr></thead><tbody>{fields.map(field=><tr key={field.field_id}><td><strong>{field.field_id}</strong><small className="sw-table-small">{field.data_type}</small></td><td>{field.business_definition?.name_zh||'未维护'}</td><td>{field.business_definition?.definition||'未维护'}</td><td>{showValue(field.semantic_role)}</td><td>{field.nullable===null?'未采集':String(field.nullable)}</td><td><button className="btn" onClick={()=>{setEditing({field_id:field.field_id,name_zh:field.business_definition?.name_zh||'',definition:field.business_definition?.definition||'',semantic_role:field.semantic_role,unit:copy(field.unit),classification:field.classification});setReason('');}}>维护释义</button></td></tr>)}</tbody></table></div>{editing&&<div className="sw-catalog-editor"><div className="sw-section-heading"><h3>维护字段：{editing.field_id}</h3><button className="btn" onClick={()=>setEditing(null)} disabled={busy}>取消</button></div><div className="sw-form-grid"><Text label="字段中文名称" value={editing.name_zh} onChange={value=>setEditing({...editing,name_zh:value})}/><Select label="真实语义角色" value={editing.semantic_role} options={['IDENTIFIER','ATTRIBUTE','MEASURE','STATUS','EVENT_TIME','SNAPSHOT_DATE','BUSINESS_DATE','PROCESSING_TIME']} onChange={value=>setEditing({...editing,semantic_role:value})}/><Select label="字段敏感分类" value={editing.classification} options={['PUBLIC','INTERNAL','SENSITIVE']} onChange={value=>setEditing({...editing,classification:value})}/>{editing.unit?<><UnitControl value={editing.unit} onChange={value=>setEditing({...editing,unit:value})}/><button type="button" className="btn" onClick={()=>setEditing({...editing,unit:null})}>清除未确认的单位声明</button></>:<button type="button" className="btn" onClick={()=>setEditing({...editing,unit:unitUnknown()})}>维护单位与币种</button>}<Text label="业务释义与边界" value={editing.definition} onChange={value=>setEditing({...editing,definition:value})} multiline/><Text label="修改依据 / 理由" value={reason} onChange={setReason} multiline/></div><Notice>保存产生新目录快照。要让召回或执行使用新释义，需显式修订相关物理映射并建立新的本地测试快照；不会改写已有运行。</Notice><button className="btn primary" disabled={busy||!editing.name_zh.trim()||!editing.definition.trim()||!reason.trim()} onClick={save}>{busy?'保存中…':'保存为新目录快照'}</button></div>}<details className="sw-technical"><summary>查看采集键约束与结构指纹</summary><p>约束状态：{showValue(dataset.constraints_state)}；空约束列表不证明没有键约束。</p><pre>{JSON.stringify({schema_fingerprint:dataset.schema_fingerprint,key_constraints:dataset.key_constraints},null,2)}</pre></details></>:<Notice>当前用户没有可用目录快照。目录权限与语义内容读取权限分别控制。</Notice>}
 </div>;
}
